# Generated by build.py from recipe.yml for recipe scp-serve-a-host-certificate. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'ssh-keygen -t ed25519 -N "" -C "" -f ca'
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -s ca -I surl-host -h -n 127.0.0.1 host_key.pub'
cmd /c 'ssh-keygen -t ed25519 -N "" -f spare_key'
cmd /c 'ssh-keygen -s ca -I spare-host -h -n 127.0.0.1 spare_key.pub'
cmd /c 'ssh-keygen -t ed25519 -N "" -f client_key'
cmd /c 'curl -s --variable ca_key@ca.pub --expand-write-out " @cert-authority * {{ca_key}}" -o NUL file:///NUL > known_hosts'
cmd /c 'ssh-keygen -t ed25519 -N "" -C "" -f other_ca'
cmd /c 'curl -s --variable ca_key@other_ca.pub --expand-write-out " @cert-authority * {{ca_key}}" -o NUL file:///NUL > other_known_hosts'
cmd /c 'ssh-keygen -lf host_key.pub > fingerprint.txt'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--hostkey', 'host_key', '--hostcert', 'host_key-cert.pub', '--authorized-keys', 'alice:client_key.pub', '--user', 'alice:s3cret', 'scp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sftp -q -b get.sftp -P 8080 -i client_key -o UserKnownHostsFile=known_hosts -o GlobalKnownHostsFile=NUL -o StrictHostKeyChecking=yes alice@127.0.0.1 } finally { Stop-Process $server0 }
